var n=`1165-pozole-rojo`;var o=`world-1165`;var a=`MX`;var t=`central-america-caribbean`;var r=8;var s=343;var l={en:`Pozole Rojo`,ua:`Червоне позоле`};var d={en:`Pozole Rojo is a dish from Mexico prepared with hominy, pork shoulder, yellow onion, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Червоне позоле, страва кухні країни Мексика, яку готують із таких продуктів: ніштамалізована кукурудза, свиняча лопатка, жовта цибуля, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Soak the dried beans in ample clean cold water for about 180 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 180 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:180,i:[[`hominy`,530,`g`],[`water`,1e3,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 110 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 110 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:110,i:[[`pork-shoulder`,860,`g`],[`water`,1550,`ml`],[`yellow-onion`,170,`g`],[`garlic`,6,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`dried-guajillo-chilies`,5,`pcs`],[`dried-ancho-chilies`,3,`pcs`],[`chicken-stock`,250,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`radish`,180,`g`],[`white-cabbage`,220,`g`],[`dried-oregano`,5,`g`],[`lime`,2,`pcs`]]}];var g={slug:n,id:o,country:`MX`,region:t,servings:8,minutes:343,title:l,text:d,steps:m};export{a as country,g as default,o as id,s as minutes,t as region,r as servings,n as slug,m as steps,d as text,l as title};